using System.Security.Cryptography;using System.Text;namespace QuantForge.Core;public sealed record StrategyDraftReview(string ReviewFingerprint,string DraftFingerprint,string AdmissionArtifactFingerprint,string StrategyId,string StrategyFingerprint,bool ReadyForResearch,bool CanSubmitOrders,IReadOnlyList<string> Diagnostics);public static class StrategyDraftReviewRules{public static StrategyDraftReview Create(StrategyDraft draft,StrategyAdmissionArtifact artifact){StrategyDraftRules.Validate(draft);StrategyAdmissionArtifactRules.Validate(artifact);var diagnostics=new List<string>();var manifest=artifact.Envelope.Manifest;if(!string.Equals(draft.StrategyId,manifest.StrategyId,StringComparison.Ordinal))diagnostics.Add("strategy-id-mismatch");if(!string.Equals(draft.SourceFingerprint,manifest.SourceFingerprint,StringComparison.Ordinal))diagnostics.Add("strategy-fingerprint-mismatch");var ready=diagnostics.Count==0;var text=string.Join("|",draft.DraftFingerprint,artifact.ArtifactFingerprint,ready,string.Join(",",diagnostics));var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,draft.DraftFingerprint,artifact.ArtifactFingerprint,draft.StrategyId,draft.SourceFingerprint,ready,false,diagnostics);}public static void RequireReady(StrategyDraftReview value){if(!value.ReadyForResearch||value.CanSubmitOrders||value.Diagnostics.Count!=0)throw new InvalidOperationException("Strategy draft review is not eligible for research launch.");}}
